mapper.select:
SELECT key,
FROM publisher
WHERE key = #{key}

SELECT exists(
  SELECT key FROM publisher
  WHERE key=#{key}
)

SELECT d.origin, d.type, d.license, d.private AS privat, count(*) AS count, coalesce(sum(uc.counter), 0) AS usages

  AND d.gbif_publisher_key = #{key}
GROUP BY d.origin, d.type, d.license, d.private
